cd /app && python3 << 'PYEOF'
import pandas as pd
import numpy as np
import json

df = pd.read_csv('benchmark/data.csv')

# Recompute all extra data in one go and build the HTML report directly
scrape = pd.to_datetime('2026-03-29')
df['last_review_dt'] = pd.to_datetime(df['last_review'], errors='coerce')
df['days_since_review'] = (scrape - df['last_review_dt']).dt.days

cities = sorted(df['city'].unique())

# Basic KPIs
median_price = {city: float(df[(df['city']==city) & (df['price'].notna())]['price'].median()) if df[(df['city']==city)]['price'].notna().any() else None for city in cities}
mean_price = {city: float(df[(df['city']==city) & (df['price'].notna())]['price'].mean()) if df[(df['city']==city)]['price'].notna().any() else None for city in cities}
price_count = {city: int(df[df['city']==city]['price'].notna().sum()) for city in cities}
prof_host = {city: float((df[df['city']==city]['calculated_host_listings_count'] >= 5).mean() * 100) for city in cities}
avg_rpm = {city: float(df[df['city']==city]['reviews_per_month'].mean()) for city in cities}
mean_avail = {city: float(df[df['city']==city]['availability_365'].mean()) for city in cities}
entire_share = {city: float((df[df['city']==city]['room_type'] == 'Entire home/apt').mean() * 100) for city in cities}

# Room type distribution
room_types = ['Entire home/apt', 'Private room', 'Hotel room', 'Shared room']
room_dist = {}
for city in cities:
    sub = df[df['city']==city]
    total = len(sub)
    room_dist[city] = {rt: float((sub['room_type']==rt).mean() * 100) for rt in room_types}

# Price by room type
price_by_room = {}
for city in cities:
    price_by_room[city] = {}
    for rt in room_types:
        sub = df[(df['city']==city) & (df['room_type']==rt) & (df['price'].notna())]['price']
        price_by_room[city][rt] = {'median': float(sub.median()) if len(sub)>0 else None, 'mean': float(sub.mean()) if len(sub)>0 else None, 'count': int(len(sub))}

# Minimum nights buckets
min_buckets = ['1 night', '2-3 nights', '4-7 nights', '8-30 nights', '31+ nights']
min_nights_buckets = {}
for city in cities:
    sub = df[df['city']==city]['minimum_nights']
    total = len(sub)
    min_nights_buckets[city] = {
        '1 night': float((sub == 1).mean() * 100),
        '2-3 nights': float(((sub >= 2) & (sub <= 3)).mean() * 100),
        '4-7 nights': float(((sub >= 4) & (sub <= 7)).mean() * 100),
        '8-30 nights': float(((sub >= 8) & (sub <= 30)).mean() * 100),
        '31+ nights': float((sub >= 31).mean() * 100),
    }

# Availability buckets
avail_buckets = ['highly_available (>300 days)', 'moderate (100-300)', 'low (<100)', 'zero']
avail_buckets_data = {}
for city in cities:
    sub = df[df['city']==city]['availability_365']
    total = len(sub)
    avail_buckets_data[city] = {
        'highly_available (>300 days)': float((sub > 300).mean() * 100),
        'moderate (100-300)': float(((sub >= 100) & (sub <= 300)).mean() * 100),
        'low (<100)': float((sub < 100).mean() * 100),
        'zero': float((sub == 0).mean() * 100),
    }

# Review recency
pct_review_12m = {}
pct_review_24m = {}
pct_no_reviews = {}
median_days_since = {}
for city in cities:
    sub = df[df['city']==city]
    total = len(sub)
    pct_no_reviews[city] = float((sub['number_of_reviews']==0).mean() * 100)
    ds = sub['days_since_review']
    pct_review_12m[city] = float(((ds <= 365) & (ds.notna())).sum() / total * 100)
    pct_review_24m[city] = float(((ds <= 730) & (ds.notna())).sum() / total * 100)
    median_days_since[city] = float(ds.median()) if ds.notna().any() else None

# Host concentration
total_listings = {city: int(len(df[df['city']==city])) for city in cities}

# Super-professional hosts
super_prof = {city: float((df[df['city']==city]['calculated_host_listings_count'] >= 20).mean() * 100) for city in cities}

# Price dispersion (CV)
price_cv = {}
for city in cities:
    sub = df[(df['city']==city) & (df['price'].notna())]['price']
    if len(sub) > 0 and sub.mean() != 0:
        price_cv[city] = float(sub.std() / sub.mean())
    else:
        price_cv[city] = None

# Save all
all_data = {
    'cities': cities,
    'median_price': median_price,
    'mean_price': mean_price,
    'price_count': price_count,
    'prof_host': prof_host,
    'avg_rpm': avg_rpm,
    'mean_avail': mean_avail,
    'entire_share': entire_share,
    'room_dist': room_dist,
    'price_by_room': price_by_room,
    'min_nights_buckets': min_nights_buckets,
    'avail_buckets': avail_buckets_data,
    'pct_review_12m': pct_review_12m,
    'pct_review_24m': pct_review_24m,
    'pct_no_reviews': pct_no_reviews,
    'median_days_since': median_days_since,
    'total_listings': total_listings,
    'super_prof': super_prof,
    'price_cv': price_cv,
}
with open('/app/output/all_data.json', 'w') as f:
    json.dump(all_data, f, indent=2, default=str)
print("Saved all_data.json")
